const raw = $input.first().json;
const b = raw.body ?? raw;
const shift_id = String(b.shift_id ?? '').trim();
const station_id = String(b.station_id ?? '').trim();
if (!shift_id || !station_id) {
  throw new Error('Payload must include shift_id and station_id, e.g. {"station_id":"ST01","shift_id":"ST01-20261003-A"}');
}
return [{ json: { shift_id, station_id, shift_end: b.shift_end ?? null, triggered_at: new Date().toISOString() } }];

// ===== Wet-stock reconciliation: expected vs actual, per tank =====
const num = (v) => {
  if (v === undefined || v === null) return null;
  const s = String(v).replace(/,/g, '').trim();
  if (s === '') return null;
  const n = Number(s);
  return Number.isFinite(n) ? n : null;
};
const r1 = (x) => Math.round(x * 10) / 10;
const rows = (name) => $(name).all().map((i) => i.json).filter((r) => r && Object.keys(r).length > 0);

const { shift_id, station_id } = $('Validate Webhook Data').first().json;

const tanks = rows('Get Tanks').filter(
  (t) => String(t.station_id) === station_id && String(t.active).toUpperCase() !== 'FALSE'
);
if (!tanks.length) throw new Error(`No active tanks for station ${station_id} - check the Tanks sheet`);

const readings = rows('Get Tank Readings').filter((r) => String(r.shift_id) === shift_id);
const sales = rows('Get Nozzle Sales').filter((r) => String(r.shift_id) === shift_id);
const deliveries = rows('Get Deliveries').filter((r) => String(r.shift_id) === shift_id);
// Sheet order == chronological order (rows are appended)
const history = rows('Get Audit History').filter(
  (r) => String(r.station_id) === station_id && String(r.shift_id) !== shift_id
);
const now = new Date().toISOString();
const out = [];

for (const t of tanks) {
  const tank_id = String(t.tank_id);
  const product = t.product || '';
  const capacity = num(t.capacity_l);
  const absTol = num(t.abs_tolerance_l) ?? 40;
  const pctTol = num(t.pct_tolerance) ?? 0.5;
  const zThr = num(t.z_threshold) ?? 3;
  const minHist = num(t.min_history) ?? 5;
  const coef = num(t.thermal_coef) ?? 0.001;
  const flags = [];
  const base = { logged_at: now, shift_id, station_id, tank_id, product };

  const gap = (reason) => {
    out.push({
      ...base, opening_l: '', deliveries_l: '', net_sales_l: '', expected_l: '', actual_l: '',
      variance_l: '', variance_pct: '', tolerance_l: '', baseline_mean_l: '', baseline_std_l: '',
      z_score: '', direction: 'DATA_GAP', severity: 'DATA_GAP', risk_score: 0,
      flags: [reason, ...flags].join(' | '), customer_risk: 'NONE', nozzles: [],
      notify: true, needs_ai: false, ai_context: null,
    });
  };

  // ---- 1. Inputs + sanity checks (honest station: bad data != theft) ----
  const rd = readings.find((r) => String(r.tank_id) === tank_id);
  if (!rd) { gap('MISSING_TANK_READING'); continue; }
  const opening = num(rd.opening_l);
  const closing = num(rd.closing_l);
  if (opening === null || closing === null || opening < 0 || closing < 0) { gap('INVALID_TANK_READING'); continue; }
  if (capacity !== null && (opening > capacity || closing > capacity)) { gap('DIP_EXCEEDS_CAPACITY'); continue; }

  const tankSales = sales.filter((s) => String(s.tank_id) === tank_id);
  if (!tankSales.length) { gap('MISSING_NOZZLE_SALES'); continue; }

  // ---- 2. Nozzle sales (totalizer delta) ----
  let metered = 0, pumpTest = 0, meterIssue = false;
  const nozzles = [];
  for (const s of tankSales) {
    const o = num(s.opening_totalizer_l);
    const c = num(s.closing_totalizer_l);
    if (o === null || c === null) { flags.push(`BAD_TOTALIZER:${s.nozzle_id}`); meterIssue = true; continue; }
    if (c < o) { flags.push(`TOTALIZER_ROLLBACK:${s.nozzle_id}`); meterIssue = true; continue; }
    metered += c - o;
    pumpTest += num(s.pump_test_return_l) ?? 0; // calibration fuel poured back in the tank
    nozzles.push({ nozzle_id: s.nozzle_id, litres: r1(c - o) });
  }
  if (!nozzles.length) { gap('NO_VALID_NOZZLE_DATA'); continue; }
  const netSales = metered - pumpTest;

  // ---- 3. Deliveries (dip-measured wins over invoice; shortfall flagged separately) ----
  let received = 0, deliveryShort = false;
  for (const d of deliveries.filter((x) => String(x.tank_id) === tank_id)) {
    const inv = num(d.invoice_litres);
    const b = num(d.dip_before_l);
    const a = num(d.dip_after_l);
    const measured = b !== null && a !== null ? a - b : null;
    received += measured ?? inv ?? 0;
    if (inv !== null && measured !== null) {
      const diff = inv - measured;
      const dTol = Math.max(absTol, 0.005 * inv);
      if (diff > dTol) { flags.push(`DELIVERY_SHORT:${d.delivery_id}:${r1(diff)}L`); deliveryShort = true; }
      else if (-diff > dTol) flags.push(`DELIVERY_OVER:${d.delivery_id}:${r1(-diff)}L`);
    }
  }

  // ---- 4. Expected vs actual (temperature-corrected) ----
  const tO = num(rd.opening_temp_c);
  const tC = num(rd.closing_temp_c);
  const thermal = tO !== null && tC !== null ? ((opening + closing) / 2) * coef * (tC - tO) : 0;
  const expected = opening + received - netSales;
  const variance = closing - expected - thermal;
  const tolerance = Math.max(absTol, (pctTol / 100) * Math.max(netSales, 0));
  const ratio = Math.abs(variance) / tolerance;

  // ---- 5. Baseline from this tank's own history (clean rows only) ----
  const tankHist = history.filter((h) => String(h.tank_id) === tank_id);
  const clean = tankHist
    .filter((h) => ['OK', 'WATCH'].includes(String(h.severity)))
    .map((h) => num(h.variance_l))
    .filter((v) => v !== null)
    .slice(-20);
  let mean = null, std = null, z = null;
  if (clean.length >= minHist) {
    mean = clean.reduce((a, b) => a + b, 0) / clean.length;
    std = Math.sqrt(clean.reduce((a, b) => a + (b - mean) ** 2, 0) / (clean.length - 1));
    z = (variance - mean) / Math.max(std, 0.25 * tolerance); // floor stops tiny-std blowups
  }
  const absZ = z === null ? 0 : Math.abs(z);

  // ---- 6. Persistent drift: slow leak hides under per-shift tolerance ----
  const prev = tankHist.map((h) => num(h.variance_l)).filter((v) => v !== null).slice(-2);
  let drift = false;
  if (prev.length === 2 && variance !== 0) {
    const three = [...prev, variance];
    drift =
      three.every((v) => Math.sign(v) === Math.sign(variance)) &&
      three.every((v) => Math.abs(v) >= 0.5 * tolerance) &&
      Math.abs(three.reduce((a, b) => a + b, 0)) > 2 * tolerance;
    if (drift) flags.push('PERSISTENT_DRIFT');
  }

  // ---- 7. Severity ----
  let severity = 'OK';
  if (ratio >= 1 || (z !== null && absZ >= 2 && ratio >= 0.5)) severity = 'WATCH';
  if (ratio >= 2 || (z !== null && absZ >= zThr && ratio >= 1) || drift || meterIssue) severity = 'ALERT';
  if (ratio >= 4 || (ratio >= 2 && drift) || (z !== null && absZ >= 2 * zThr && ratio >= 2)) severity = 'CRITICAL';

  // A nozzle with a bad/rolled-back totalizer was excluded, so the variance is unreliable: never CRITICAL on that alone
  if (meterIssue) {
    flags.push('VARIANCE_UNRELIABLE_NOZZLE_EXCLUDED');
    if (severity === 'CRITICAL') severity = 'ALERT';
  }

  // ---- 8. Direction + customer impact ----
  // LOSS    = less fuel in tank than books say -> leak / theft / meters under-reading
  // SURPLUS = MORE fuel in tank than books say -> meters over-reading (customers short-changed) / unrecorded delivery / dip error
  const direction = ratio >= 1 ? (variance < 0 ? 'LOSS' : 'SURPLUS') : 'WITHIN_TOLERANCE';
  let customerRisk = 'NONE';
  if (direction === 'SURPLUS') customerRisk = ratio >= 2 ? 'HIGH' : 'WATCH';
  if (customerRisk === 'HIGH') flags.push('CUSTOMER_RISK_METER_OVER_REGISTRATION');

  // ---- 9. Risk score 0-100 ----
  let risk = z === null
    ? Math.min(80, ratio * 20)
    : Math.min(50, ratio * 12.5) + Math.min(30, absZ * 6);
  if (drift) risk += 20;
  if (meterIssue) risk += 15;
  risk = Math.round(Math.min(100, risk));

  const notify = ['ALERT', 'CRITICAL'].includes(severity) || deliveryShort;
  const needsAi = ['WATCH', 'ALERT', 'CRITICAL'].includes(severity);

  const rec = {
    ...base,
    opening_l: r1(opening),
    deliveries_l: r1(received),
    net_sales_l: r1(netSales),
    expected_l: r1(expected),
    actual_l: r1(closing),
    variance_l: r1(variance),
    variance_pct: netSales > 0 ? r1((variance / netSales) * 100) : 0,
    tolerance_l: r1(tolerance),
    baseline_mean_l: mean === null ? '' : r1(mean),
    baseline_std_l: std === null ? '' : r1(std),
    z_score: z === null ? '' : r1(Math.max(-99, Math.min(99, z))),
    direction,
    severity,
    risk_score: risk,
    flags: flags.join(' | '),
    customer_risk: customerRisk,
    nozzles,
    notify,
    needs_ai: needsAi,
  };

  rec.ai_context = {
    station_id, shift_id,
    tank: { tank_id, product, capacity_l: capacity },
    opening_l: rec.opening_l, closing_l: rec.actual_l,
    opening_temp_c: tO, closing_temp_c: tC, thermal_effect_l: r1(thermal),
    deliveries_received_l: rec.deliveries_l,
    metered_sales_l: r1(metered), pump_test_returned_l: r1(pumpTest), net_sales_l: rec.net_sales_l,
    nozzle_breakdown_l: nozzles,
    expected_closing_l: rec.expected_l,
    variance_l: rec.variance_l, variance_pct_of_sales: rec.variance_pct,
    tolerance_l: rec.tolerance_l, variance_to_tolerance_ratio: r1(ratio),
    direction, customer_risk: customerRisk,
    baseline: { shifts_used: clean.length, mean_l: rec.baseline_mean_l, std_l: rec.baseline_std_l, z_score: rec.z_score },
    last_8_clean_variances_l: clean.slice(-8),
    prior_two_variances_l: prev,
    persistent_drift: drift,
    flags: flags,
    rule_engine_severity: severity,
    risk_score: risk,
  };
  out.push(rec);
}

return out.map((json) => ({ json }));

const base = $('Check for AI Analysis Need').item.json;
const raw = String($json.text ?? $json.output ?? '');
let ai = null;
try {
  const s = raw.indexOf('{');
  const e = raw.lastIndexOf('}');
  ai = JSON.parse(raw.slice(s, e + 1));
} catch (err) { ai = null; }
if (!ai || typeof ai !== 'object') {
  ai = {
    verdict: 'NEEDS_RECHECK', confidence: 0,
    summary: 'AI output could not be parsed - review the numbers manually. Raw: ' + raw.slice(0, 300),
    likely_causes: [], customer_impact: '',
    actions: ['Re-dip the tank with a calibrated stick', 'Review the flags and nozzle breakdown'],
  };
}
const arr = (v) => (Array.isArray(v) ? v.map(String) : v ? [String(v)] : []);
const causes = arr(ai.likely_causes);
const actions = arr(ai.actions);
return {
  json: {
    ...base,
    ai_verdict: String(ai.verdict || 'NEEDS_RECHECK'),
    ai_confidence: ai.confidence ?? '',
    ai_summary: String(ai.summary || ''),
    ai_causes: causes.join(' | '),
    ai_actions: actions.join(' | '),
    ai_customer_impact: String(ai.customer_impact || ''),
    ai_causes_list: causes,
    ai_actions_list: actions,
  },
};

const j = $json;
const gap = j.severity === 'DATA_GAP';
return {
  json: {
    ...j,
    ai_verdict: gap ? 'DATA_GAP' : 'NO_ISSUE',
    ai_confidence: '',
    ai_summary: gap
      ? 'Data incomplete - reconciliation skipped. Fix the source rows and re-run the shift.'
      : 'Within tolerance - no investigation needed.',
    ai_causes: '',
    ai_actions: '',
    ai_customer_impact: '',
    ai_causes_list: [],
    ai_actions_list: [],
  },
};

const fmt = (n, d = 1) =>
  n === '' || n === null || n === undefined || Number.isNaN(Number(n))
    ? 'n/a'
    : Number(n).toLocaleString('en-US', { maximumFractionDigits: d });
const signed = (n) => (n === '' || n == null ? 'n/a' : (Number(n) > 0 ? '+' : '') + fmt(n));

const items = $('Merge Analysis Records').all().map((i) => i.json);
return items.map((j) => {
  const where = `${j.station_id} | ${j.tank_id} (${j.product}) | ${j.shift_id}`;
  const lines = [];
  let head;
  if (j.severity === 'DATA_GAP') {
    head = `:grey_question: *DATA GAP* - ${where}`;
    lines.push(`Reconciliation skipped: \`${j.flags}\``);
    lines.push('_This is a data problem, not an accusation. Fix the source rows and re-run the shift._');
  } else {
    const label =
      j.severity === 'CRITICAL' ? ':rotating_light: *CRITICAL VARIANCE*'
      : j.severity === 'ALERT' ? ':warning: *VARIANCE ALERT*'
      : ':truck: *DELIVERY CHECK*';
    head = `${label} - ${where}`;
    lines.push(
      `*Variance:* ${signed(j.variance_l)} L (expected ${fmt(j.expected_l)} L, actual ${fmt(j.actual_l)} L) | tolerance +/-${fmt(j.tolerance_l)} L | z ${fmt(j.z_score)} | *risk ${j.risk_score}/100*`
    );
    lines.push(`*Pattern:* ${j.direction}${j.customer_risk && j.customer_risk !== 'NONE' ? ` | customer risk: ${j.customer_risk}` : ''}`);
    if (j.customer_risk === 'HIGH') {
      const nz = (j.nozzles || []).map((n) => n.nozzle_id).join(', ');
      lines.push(
        `:mag: *Customer impact:* more fuel is in the tank than the meters imply, so nozzles (${nz}) may be over-registering and customers short-changed. Run a 5 L test-measure on each before the next sale.`
      );
    }
    if (j.flags) lines.push(`*Flags:* \`${j.flags}\``);
    if (j.ai_verdict && !['NO_ISSUE', 'DATA_GAP'].includes(j.ai_verdict)) {
      lines.push(`*AI verdict:* ${j.ai_verdict}${j.ai_confidence !== '' ? ` (${j.ai_confidence}% confidence)` : ''}`);
      if (j.ai_summary) lines.push(j.ai_summary);
      const c = (j.ai_causes_list || []).slice(0, 3);
      if (c.length) lines.push('*Likely causes:*\n' + c.map((x) => `- ${x}`).join('\n'));
      const a = (j.ai_actions_list || []).slice(0, 4);
      if (a.length) lines.push('*Do now:*\n' + a.map((x, k) => `${k + 1}. ${x}`).join('\n'));
    }
    lines.push('_Variance is a signal, not an accusation. Re-dip and verify before escalating._');
  }
  return { json: { ...j, slack_text: [head, ...lines].join('\n') } };
});

const items = $('Merge Analysis Records').all().map((i) => i.json);
const first = items[0] || {};
return [{
  json: {
    ok: true,
    station_id: first.station_id,
    shift_id: first.shift_id,
    tanks_analysed: items.length,
    alerts_raised: items.filter((i) => i.notify).length,
    results: items.map((i) => ({
      tank_id: i.tank_id,
      severity: i.severity,
      direction: i.direction,
      variance_l: i.variance_l,
      tolerance_l: i.tolerance_l,
      risk_score: i.risk_score,
      customer_risk: i.customer_risk,
      ai_verdict: i.ai_verdict,
      flags: i.flags,
    })),
  },
}];
